use mlx_rs::{Array,Device,Dtype,ops::addmm};use std::{error::Error,fs,path::PathBuf};
fn run()->Result<(),Box<dyn Error>>{let a:Vec<_>=std::env::args().collect();if a.len()!=3{return Err("usage INPUT OUT".into())}let s=PathBuf::from(&a[1]);let o=PathBuf::from(&a[2]);fs::create_dir(&o)?;for stage in ["first","second"]{let load=|k:&str|mlx_rs::with_device(Device::cpu(),||Array::load_numpy(s.join(format!("{stage}-{k}.npy"))));let x=load("input")?;let w=load("weight")?.transpose_axes(&[1,0])?;let b=load("bias")?;let h=addmm(&b,&x,&w,None,None)?;let f=addmm(b.as_dtype(Dtype::Float32)?,x.as_dtype(Dtype::Float32)?,w.as_dtype(Dtype::Float32)?,None,None)?.as_dtype(Dtype::Float16)?;mlx_rs::transforms::eval([&h,&f])?;h.save_numpy(o.join(format!("{stage}-half.npy")))?;f.save_numpy(o.join(format!("{stage}-f32-opmath.npy")))?;}Ok(())}fn main()->Result<(),Box<dyn Error>>{mlx_rs::with_device(Device::gpu(),run)}
